# output to file /tpcds/data/queries_annotated.sql/*.sql
#!/usr/bin/env python3

import re
from pathlib import Path

import sqlglot
from sqlglot import ErrorLevel

from ast_visitor import rewrite_sql


def preprocess_oracle_sql(sql: str) -> str:
    """Fix known Oracle TPC-DS dgen idioms that sqlglot's oracle reader
    mishandles, before we ever hand the text to sqlglot.

    1. `DATE_EXPR + N days` / `- N days` (and the `+ N AS days` variant that
       appears in some TPC-DS templates, e.g. query 14): this is TPC-DS's
       own `dsqgen` idiom, present in the official .tpl templates regardless
       of target dialect -- not something our earlier Oracle transpile step
       introduced. It isn't valid SQL as written in any dialect; sqlglot's
       oracle reader parses the trailing bare word as an implicit alias
       (same rule as `SELECT x y` meaning `SELECT x AS y`), and the postgres
       writer then re-emits that bogus alias as `AS days` -- landing inside
       a BETWEEN's parens, where Postgres's grammar rejects it outright
       ("syntax error at or near AS"). We rewrite it into an explicit,
       unambiguous interval expression, `+ INTERVAL 'N day'`, which is valid
       in both Oracle and Postgres and transpiles correctly.
    2. `WHERE ROWNUM <= N`: TPC-DS's Oracle templates paginate this way,
       but sqlglot does not translate `rownum` into Postgres's `LIMIT` --
       it passes it through unchanged, which fails at execution time in
       Postgres (no `rownum` pseudo-column exists there). We rewrite it to
       `LIMIT N` ourselves, either replacing the whole WHERE clause if
       rownum was its only condition, or removing just that AND-ed
       conjunct otherwise.
    """
    # Only touch text OUTSIDE single-/double-quoted literals, so we never
    # rewrite something that merely looks like "- N days" inside a quoted
    # alias or string value.
    quoted_span = re.compile(r"""('(?:[^']|'')*'|"(?:[^"]|"")*")""")
    parts = quoted_span.split(sql)

    def fix_date_arith(segment: str) -> str:
        return re.sub(
            r'([+\-])\s*(\d+)\s*(?:as\s+)?(days?|months?|years?|weeks?|hours?)\b',
            lambda m: f"{m.group(1)} INTERVAL '{m.group(2)} {m.group(3).rstrip('s')}'",
            segment,
            flags=re.IGNORECASE,
        )

    # re.split with a capturing group alternates: [unquoted, quoted, unquoted, quoted, ...]
    sql = ''.join(
        part if i % 2 == 1 else fix_date_arith(part)
        for i, part in enumerate(parts)
    )

    parts = sql.split(';')
    fixed_parts = []
    for part in parts:
        m = re.search(r'\bwhere\s+rownum\s*<=\s*(\d+)\s*$',
                      part, flags=re.IGNORECASE)
        if m:
            part = part[:m.start()].rstrip() + f' LIMIT {m.group(1)}'
        else:
            m2 = re.search(r'\band\s+rownum\s*<=\s*(\d+)\b',
                           part, flags=re.IGNORECASE)
            if m2:
                limit_n = m2.group(1)
                part = part[:m2.start()] + part[m2.end():]
                part = part.rstrip() + f' LIMIT {limit_n}'
        fixed_parts.append(part)

    return ';'.join(fixed_parts)


def convert_to_postgres(sql: str, source_dialect: str | None):
    """
    Convert SQL generated by a TPC-DS template to PostgreSQL.

    Args:
        sql: Source SQL.
        source_dialect: SQLGlot source dialect, e.g. "oracle", "db2",
            "tsql", "netezza", or None for generic/ANSI SQL.

    Returns:
        PostgreSQL SQL.
    """
    # sqlglot.transpile() both parses and generates SQL in the target
    # dialect. Calling transpile with a single statement is convenient
    # here because each TPC-DS query is in its own file.
    statements = sqlglot.transpile(
        sql,
        read=source_dialect,
        write="postgres",
        error_level=ErrorLevel.RAISE,
    )

    return statements
    # # If sqlglot produces multiple statements, preserve them all.
    # return ";\n".join(stmt.rstrip(";") for stmt in statements) + ";"

def fix_round_double_precision(sql: str) -> str:
    """Fix `round(CAST(expr AS DOUBLE PRECISION) / divisor, n)` -> use NUMERIC
    cast instead, since Postgres has no round(double precision, integer)
    overload. Only touches casts that sit inside a round(...) call's first
    argument, immediately followed by `/ ... ,`.
    """
    pattern = re.compile(
        r'\bROUND\(\s*CAST\(([^()]+(?:\([^()]*\)[^()]*)*)\s+AS\s+DOUBLE\s+PRECISION\)',
        re.IGNORECASE,
    )
    return pattern.sub(lambda m: f"ROUND(CAST({m.group(1)} AS NUMERIC)", sql)

def process_file(input_path: Path, output_path: Path, postgres_path: Path, source_dialect) -> None:
    """Convert and annotate a single SQL file."""
    print(f"Processing {input_path}")

    sql = input_path.read_text(encoding="utf-8")
    sql = preprocess_oracle_sql(sql)

    # -----------------------------------------------------------------------
    # Step 1: TPC-DS generated SQL -> PostgreSQL
    # -----------------------------------------------------------------------
    try:
        postgres_sql = convert_to_postgres(sql, source_dialect)
        postgres_sql = [fix_round_double_precision(s) for s in postgres_sql]
    except Exception:
        print(f"To postgres {Exception}")

    # -----------------------------------------------------------------------
    # Step 2: PostgreSQL SQL -> custom AST -> annotation rewrite
    # -----------------------------------------------------------------------

    annotated_statements = []
    postgres_statements = []
    count = 0

    for statement in postgres_sql:
        try:
            rewritten = rewrite_sql(statement)
            annotated_statements.append(rewritten)
            postgres_statements.append(statement)
        except Exception as e:
            print(f"Error at index {count}:")
            print(statement)
            print(f"rewrite error: {e}")
        count += 1

    # Write original PostgreSQL statements
    postgres_path.write_text(
        ";\n".join(s.rstrip(";") for s in postgres_statements) + ";\n",
        encoding="utf-8",
    )

    # Write rewritten statements
    output_path.write_text(
        ";\n".join(s.rstrip(";") for s in annotated_statements) + ";\n",
        encoding="utf-8",
    )


def process_directory(input_dir, output_dir, postgres_dir, source_dialect):
    """
    Process all SQL files in input_dir.
    """
    output_dir.mkdir(
        parents=True, exist_ok=True)  # avoid silent failure if it doesn't exist
    input_files = sorted(input_dir.glob("*.sql"))
    print(f"Found {len(input_files)} files")

    for input_path in input_files:
        output_path = output_dir / input_path.name
        postgres_path = postgres_dir / input_path.name

        try:
            process_file(input_path, output_path, postgres_path, source_dialect)
            print("done")
        except Exception:
            print(f"Failed to process {input_path}")


def main() -> None:
    process_directory(
        Path("tpcds/data/1/queries"),
        Path("tpcds/data/1/queries_annotated"),
        Path("tpcds/data/1/queries_baseline"),
        "oracle"
    )


if __name__ == "__main__":
    main()
